style.css:
@-moz-document domain("online.ug.edu.ge") {
.HeadFirst,
#cssmenu ul.dropdown,
#cssmenu ul.dropdown li > a {
    background-image: none;
    background-color: #1d6986;
}

#cssmenu ul.dropdown {
    width: auto;
}

.buttons {
    margin-top: 5px;
    border-top-left-radius: 1em;
}

#cssmenu  ul.sub_menu>input{
      margin: 5px 15px;
}

#cssmenu li ul{
    padding-top: 35px;
    top: 0px;
    max-height: 70vh;

  flex-direction: column;
  flex-wrap: wrap;
  width: max-content;
}

#cssmenu li:hover ul{
  display: flex !important;
}

#cssmenu li li{
      width: auto;
}

#cssmenu li ul{
  padding-top: 0 !important;
  top: 36px !important;
}
}
